import{_ as r,B as s,o as i,c as d,a8 as l,a as t,E as n,f as o}from"./chunks/framework.CNIpabDg.js";const y=JSON.parse(`{"title":"Synth (executable)","description":"Understand Xila Synth's bounded WASM audio generation and native/browser playback paths.","frontmatter":{"layout":"doc","docType":"explanation","description":"Understand Xila Synth's bounded WASM audio generation and native/browser playback paths."},"headers":[],"relativePath":"explanation/architecture/executables/synth.md","filePath":"explanation/architecture/executables/synth.md","lastUpdated":1793145952000}`),u={name:"explanation/architecture/executables/synth.md"};function c(p,e,h,b,m,g){const a=s("CodeReference");return i(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[7]||(e[7]=l('<h1 id="synth-executable" tabindex="-1">Synth (executable) <a class="header-anchor" href="#synth-executable" aria-label="Permalink to &quot;Synth (executable)&quot;">​</a></h1><p>Synth is an eight-voice instrument implemented as a <code>wasm32-wasip1</code> guest. Its waveform generation goes through the Xila audio device and shared mixer, rather than accessing native or browser sound APIs directly.</p><h2 id="controls-and-audio-path" tabindex="-1">Controls and audio path <a class="header-anchor" href="#controls-and-audio-path" aria-label="Permalink to &quot;Controls and audio path&quot;">​</a></h2><p>The graphical keyboard supports octaves <strong>2–6</strong>, sine/square/triangle waveforms and 10% volume steps (70% initially). Note presses and releases control playback; changing octave releases any held notes. The controls are session-local.</p><p>The instrument uses bounded PCM blocks, with at most one retained <strong>128-frame block</strong> per turn. Partial writes and output backpressure do not create an unbounded queue. Eight synthesis voices do <strong>not</strong> imply support for eight simultaneous fingers: the current input driver exposes one pointer.</p><p>The native example routes audio to the system&#39;s default output. In the browser, the page&#39;s <strong>Enable audio</strong> control must be activated by a user gesture before playback is available. If Synth is already running, use <strong>Retry audio</strong>.</p><h2 id="failure-boundaries" tabindex="-1">Failure boundaries <a class="header-anchor" href="#failure-boundaries" aria-label="Permalink to &quot;Failure boundaries&quot;">​</a></h2><p>When an audio backend cannot start or stream writes fail, Synth remains interactive in <strong>silent mode</strong>. Its controls still respond; enabling audio and retrying may restore playback. Closing the window stops the notes and releases the stream.</p><p>The native and browser examples include Synth in newly seeded installations. Existing persistent disks are preserved and do not automatically install newer guest applications. Physical WT32-SC01 Plus speaker output remains pending an I2S driver and board validation; a native/browser demo does not establish it.</p><h2 id="pcm-device-interaction-and-voice-ownership" tabindex="-1">PCM device interaction and voice ownership <a class="header-anchor" href="#pcm-device-interaction-and-voice-ownership" aria-label="Permalink to &quot;PCM device interaction and voice ownership&quot;">​</a></h2><p>The guest opens <code>/devices/audio/playback</code> as a writable WASI file. It obtains <code>GET_CONFIGURATION</code>, prepares the instrument for that format, reads <code>GET_VOLUME</code>, then sets its volume to <strong>70%</strong> and sends <code>START</code>. Audio stays in a bounded PCM producer/consumer pipeline; the guest never calls <code>cpal</code> or browser audio directly.</p><p>Device controls are issued through <code>wasm::fd_control</code>, using <strong>16-byte-aligned</strong> Rust wrapper storage for typed payloads. If the host reports <code>WouldBlock</code>, the command helper retries at most <strong>eight times</strong>, waiting 1 ms between attempts. The audio update checks <code>GET_WRITABLE</code> before submitting samples; on temporary backpressure it returns without growing an unbounded queue.</p><p><code>AudioOutput</code> owns its WASI file and <code>Instrument</code>. Note state, waveform and octave belong to the guest UI. On drop, it stops all notes and attempts the <code>STOP</code> command; dropping the file then releases its stream reservation. This is a session-local instrument rather than a long-lived background sound service.</p><h2 id="failure-latency-and-output-restrictions" tabindex="-1">Failure, latency and output restrictions <a class="header-anchor" href="#failure-latency-and-output-restrictions" aria-label="Permalink to &quot;Failure, latency and output restrictions&quot;">​</a></h2><p>The guest may remain <strong>interactive but silent</strong> if audio setup fails. Audio device availability is independent of rendering: the Graphics bridge can be present while <code>/devices/audio/playback</code> or the platform playback adapter is missing. The native demo relies on a host output device, and the browser requires user activation of audio.</p><p>The synthesizer is limited to eight voices and a bounded block per turn. Voice count is independent of multi-touch support; the current pointer event model does not promise simultaneous independent fingers. The output queue may retain already submitted frames briefly after stopping notes, and a failing or contended backend can cause audible underruns.</p><h3 id="source-references" tabindex="-1">Source references <a class="header-anchor" href="#source-references" aria-label="Permalink to &quot;Source references&quot;">​</a></h3>',17)),t("ul",null,[t("li",null,[n(a,{repo:"applications",path:"executables/synth/src/device.rs"}),e[0]||(e[0]=o(" — WASI control protocol, retries and teardown.",-1))]),t("li",null,[n(a,{repo:"applications",path:"executables/synth/src/interface.rs"}),e[1]||(e[1]=o(" — keyboard, waveform and voice events.",-1))]),t("li",null,[n(a,{repo:"applications",path:"executables/synth/src/lib.rs"}),e[2]||(e[2]=o(" — bounded PCM synthesis state.",-1))]),t("li",null,[n(a,{repo:"applications",path:"executables/synth/src/install.rs"}),e[3]||(e[3]=o(" — launcher metadata.",-1))]),e[4]||(e[4]=t("li",null,[t("a",{href:"/explanation/architecture/libraries/audio.html"},"Audio device contract"),o(" — shared format and mixer semantics.")],-1))]),e[8]||(e[8]=t("h2",{id:"references",tabindex:"-1"},[o("References "),t("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),t("ul",null,[t("li",null,[n(a,{repo:"applications",path:"executables/synth/README.md"})]),t("li",null,[n(a,{repo:"applications",path:"executables/synth"})]),e[5]||(e[5]=t("li",null,[t("a",{href:"/explanation/architecture/libraries/audio.html"},"Audio library")],-1)),e[6]||(e[6]=t("li",null,[t("a",{href:"/explanation/architecture/executables/wasm.html"},"WASM executable")],-1))])])}const v=r(u,[["render",c]]);export{y as __pageData,v as default};
